def shape_sig(comp):
    """Return sorted signature of shape (relative positions)"""
    ys = sorted(set(y for y, x in comp))
    xs = sorted(set(x for y, x in comp))
    top = min(ys)
    left = min(xs)
    return sorted(sorted([(y - top, x - left) for y, x in comp]))

