print("=== Find what distinguishes the changed FR component ===\n")

for i, pair in enumerate(demo_pairs):
    inp = pair['input']
    out = pair['output']

    changes_map = {}
    for y in range(len(inp)):
        for x in range(len(inp[0])):
            if inp[y][x] != out[y][x]:
                changes_map[(y,x)] = (inp[y][x], out[y][x])

    if not changes_map:
        continue

    fr = Counter(fc for fc, tc in changes_map.values()).most_common(1)[0][0]
    to = Counter(tc for fc, tc in changes_map.values()).most_common(1)[0][0]

    # Get all FR components
    def get_all_components(grid, color):
        H, W = len(grid), len(grid[0])
        visited = [[False] * W for _ in range(H)]
        comps = []
        for y in range(H):
            for x in range(W):
                if grid[y][x] == color and not visited[y][x]:
                    cc = []
                    stack = [(y,x)]
                    visited[y][x] = True
                    while stack:
                        cy, cx = stack.pop()
                        cc.append((cy,cx))
                        for dy,dx in [(-1,0),(1,0),(0,-1),(0,1)]:
                            ny, nx = cy+dy, cx+dx
                            if 0<=ny<H and 0<=nx<W and grid[ny][nx]==color and not visited[ny][nx]:
                                visited[ny][nx] = True
                                stack.append((ny,nx))
                    comps.append(cc)
        return comps

    fr_comps = get_all_components(inp, fr)
    changed_fr_cells = set([(y,x) for (y,x), (fc, tc) in changes_map.items() if fc == fr])
    changed_comp = [c for c in fr_comps if any(yx in changed_fr_cells for yx in c)][0]

    to_cells = [(y, x) for y in range(len(inp)) for x in range(len(inp[0])) if inp[y][x] == to]

    print(f"Demo {i}: {fr} → {to}, changed {len(changed_comp)} FR cells")
    print(f"  TO cells: {len(to_cells)}")

    # Check if changed FR cells are adjacent to TO cells
    for cy, cx in changed_comp:
        for ty, tx in to_cells:
            if abs(cy-ty) <= 1 and abs(cx-tx) <= 1:
                print(f"  Changed FR at ({cy},{cx}) is adjacent to TO at ({ty},{tx})")
                break
        else:
            continue
        break
    else:
        print(f"  Changed FR not adjacent to any TO cell")

    # What other colors are adjacent to the changed component?
    all_other_colors = []
    for y in range(len(inp)):
        for x in range(len(inp[0])):
            if inp[y][x] != fr and inp[y][x] != 3:  # != 3 (bg)
                if not (inp[y][x] == fr):  # not needed
                    all_other_colors.append(inp[y][x])
    all_other_colors = set(all_other_colors)
    other_colors = [c for c in all_other_colors if c != fr and c != 3]

    print(f"  Other non-bg colors: {other_colors}")
    print()

